import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with TickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<List<CurrencyModel>>? _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;

  bool _hasMorePages = true;

  bool _initialized = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    if (!_initialized) {
      _loadInitialPage();
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // При возврате на экран обновляем данные свежим запросом с базовой валютой проекта.
    if (_initialized) {
      setState(() {
        _currentPage = 0;
        _hasMorePages = true;
      });
      _loadInitialPage();
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    // При возврате из фона обновляем данные.
    if (state == AppLifecycleState.resumed && _initialized) {
      setState(() {
        _currentPage = 0;
        _hasMorePages = true;
      });
      _loadInitialPage();
    }
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialPage() async {
    setState(() {
      _initialized = true;
    });
    final currencyRepository = context.read<CurrencyRepository>();
    _currencyListFuture = currencyRepository
        .fetchRates(const CurrencyPageRequest())
        .then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = [...value];
      _hasMorePages = page.hasMore;
      _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);

      _fadeController.forward(); // запускаем анимацию
      if (!_initialized) {
        setState(() {}); // триггерим перестроение, чтобы скрыть кнопку «Показать ещё»
      }

      currencyRepository.saveCurrencyList(value);

      return value;
    });
  }

  Future<void> _loadMore() async {
    if (!_hasMorePages || _currencyListFuture == null || !_currencyListFuture!.isCompleted) return;
    final currencyRepository = context.read<CurrencyRepository>();
    setState(() {
      _currencyListFuture = currencyRepository
          .fetchRates(CurrencyPageRequest(page: _currentPage))
          .then((CurrencyPage page) {
        _allCurrencies = [..._allCurrencies, ...page.items];
        _hasMorePages = page.hasMore;
        _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        if (!_hasMorePages) {
          setState(() {}); // триггерим перестроение, чтобы скрыть кнопку «Показать ещё»
        }
        currencyRepository.saveCurrencyList(page.items);
        return page.items;
      });
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMorePages ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (!_hasMorePages && index == data.length) {
                            return const SizedBox.shrink();
                          }
                          if (_hasMorePages && index >= data.length) {
                            return Center(
                              child: ElevatedButton(
                                onPressed: _currencyListFuture == null || !_currencyListFuture!.isCompleted
                                    ? null
                                    : _loadMore,
                                child: Text(context.loc.showMore),
                              ),
                            );
                          }
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, _hasMorePages ? 16 : 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
